() => {
  const deep = (re) => {
    const res = [];
    document.querySelectorAll('body *').forEach(el => {
      const t = (el.textContent || '').trim();
      if (!re.test(t)) return;
      const childMatch = Array.from(el.children).some(c => re.test((c.textContent || '').trim()));
      if (!childMatch) res.push({ tag: el.tagName, id: el.id, cls: el.className, text: t });
    });
    return res;
  };
  return {
    pageInfoMatches: deep(/共\d+条，\d+\/\d+页/),
    filterMatches: deep(/当前筛选：/),
    rowsCount: document.querySelectorAll('table tbody tr').length,
    tableCount: document.querySelectorAll('table').length
  };
}

